import React,{useState} from 'react';
import {View,Button,Image} from 'react-native';
import * as ImagePicker from 'expo-image-picker';
export default function Pick(){
  const[u,setU]=useState<string|null>(null);
  const go=async()=>{const p=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!p.granted)return;
    const r=await ImagePicker.launchImageLibraryAsync({mediaTypes:ImagePicker.MediaTypeOptions.Images,quality:0.8});
    if(!r.canceled)setU(r.assets[0].uri);};
  return(<View style={{padding:24}}><Button title='Pick' onPress={go}/>{u&&<Image source={{uri:u}} style={{width:200,height:200,marginTop:12}}/>}</View>);}
